import{_ as o,l as r,o as e,c as i,v as a,p,x as s,d as A,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"DeepSpeed Ulysses","description":"","frontmatter":{"title":"DeepSpeed Ulysses","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ulysses-sp.md","filePath":"llm/ulysses-sp.md","lastUpdated":1789023840000}'),h={name:"llm/ulysses-sp.md"};function m(P,l,c,E,u,_){const t=r("Mermaid");return e(),i("div",null,[l[1]||(l[1]=a('<h1 id="deepspeed-ulysses" tabindex="-1">DeepSpeed Ulysses <a class="header-anchor" href="#deepspeed-ulysses" aria-label="Permalink to &quot;DeepSpeed Ulysses&quot;">​</a></h1><div class="epigraph"><p>沿序列维切开注意力的激活，用 All-to-All 把各分片上的头凑齐再算注意力，长上下文才不必让每张卡存下整段 $s$。</p><footer>—— Jacobs 等，DeepSpeed Ulysses</footer></div><p><a href="/llm/comp-comm-overlap">上一课</a>把已有通信藏进 GEMM。长文档上采样把 \\(s\\) 推到 32k、128k 时，激活显存按 \\(s\\) 涨，TP 切的是隐藏维，挡不住序列轴。Korthikanti 的序列并行沿序列切 LayerNorm 与 Dropout；Ulysses 把注意力也做成序列维切分：先 All-to-All 换成按头完整、按序列分片，算完再 All-to-All 回去。本课不重讲重叠手法。缺口是这种序列并行（SP）与 TP、PP 如何分工，以及它与环形注意力一类长序列方法的边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>注意力激活与 KV 在训练时随 \\(s\\) 线性涨（重计算可换时间），softmax 的中间量也大。只靠 TP，每卡仍持有全长 \\(s\\)。只靠把微批切小，GEMM 效率掉、PP 气泡相对变大。需要第四维：切序列。Ulysses 的选择是：非注意力模块保持按序列分片（每卡 \\(s/P_{\\mathrm{sp}}\\)），进入注意力前 All-to-All，使每卡持有全部 \\(s\\) 但只持有部分头，用现成的融合注意力核，再 All-to-All 还原。</p><p>与 <a href="/llm/tensor-parallel">张量并行</a> 按头切注意力看起来像同一件事，分工不同：TP 切的是始终存在的头分片，通信是 All-Reduce；Ulysses 的 All-to-All 是布局变换，进出注意力各一次。两者可以叠，但要避免把头切两次切碎。</p><h3 id="通信体积" tabindex="-1">通信体积 <a class="header-anchor" href="#通信体积" aria-label="Permalink to &quot;通信体积&quot;">​</a></h3><p>All-to-All 的体积 \\(\\propto b\\times s\\times d\\)，与 TP 激活通信同阶。\\(s\\) 极大时，\\(T_{\\mathrm{comm}}\\) 可能超过注意力计算，重叠也盖不住。SP 度不是越大越好：应让每卡序列分片仍够长，注意力核有事可做。</p><p><span class="marginnote">Ulysses 不把因果掩码改成块稀疏。复杂度仍是每头 \\(O(s^2)\\)，只是分摊到不同卡的头上。真正降复杂度是 Ring Attention 或稀疏核，不是本课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定 SP 组（通常与数据并行组正交的一组卡）。前向：各模块在序列分片上算到注意力入口 → All-to-All（序列维↔头维）→ 本地 SDPA → All-to-All 回来。反向对称。与 PP 叠加时，微批的序列长度是切分后的全局 \\(s\\)，阶段边界传递的激活也是分片后的形状，协议要在框架里一次定死。</p><p>与 1F1B 的接口：SP 通信发生在阶段内部，应与阶段间发送重叠，但缓冲区不能别名。长 \\(s\\) 时优先保证 Ulysses 的 All-to-All 完成再发 PP，或给两者不同的网络优先级——拓扑课再谈。</p><h3 id="与词表无关、与-batch-有关" tabindex="-1">与词表无关、与 batch 有关 <a class="header-anchor" href="#与词表无关、与-batch-有关" aria-label="Permalink to &quot;与词表无关、与 batch 有关&quot;">​</a></h3><p>切分沿 \\(s\\)，要求打包后的序列可被 \\(P_{\\mathrm{sp}}\\) 整除，或允许 padding。指令样本变长、FIM 重排后长度变化，加载器必须按 SP 对齐补齐，否则集合通信形状不一致。这是数据课与并行课的接缝。</p><p><span class="marginnote">梯度累积把多个微批合成优化步，每微批仍要单独做 Ulysses 通信。累积不减少 SP 通信次数，只减少优化器频率。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>布局变换把「长序列、全头」的存储问题，变成「短序列分片、算注意力时换全长少头」。数学上 SDPA 不变。通信模式从规约变成置换，类似 MoE 的 All-to-All，但置换键是序列块与头，不是专家 id。落后者对这种密集同步更敏感：一卡慢，整个 SP 组停。</p>',17)),(e(),p(n,null,{default:s(()=>[d(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%BA%8F%E5%88%97%E5%88%86%E7%89%87%E4%B8%8A%E7%9A%84%E9%9D%9E%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%20--%3E%20A2A1%5B%22All-to-All%20%E6%8D%A2%E6%88%90%E6%8C%89%E5%A4%B4%22%5D%0A%20%20A2A1%20--%3E%20ATT%5B%22%E6%9C%AC%E5%9C%B0%20SDPA%22%5D%0A%20%20ATT%20--%3E%20A2A2%5B%22All-to-All%20%E6%8D%A2%E5%9B%9E%E5%BA%8F%E5%88%97%E5%88%86%E7%89%87%22%5D%0A%20%20A2A2%20--%3E%20NEXT%5B%22%E5%90%8E%E7%BB%AD%20MLP%20%2F%20%E6%AE%8B%E5%B7%AE%22%5D%0A"})]),fallback:s(()=>[...l[0]||(l[0]=[A(" Loading... ",-1)])]),_:1})),l[2]||(l[2]=a('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Ulysses 救不了注意力平方复杂度的墙，只救显存与部分墙上时间。上下文再长应换算法。它与 DualPipe 双流叠加时，All-to-All 次数翻倍，需要实测。下一课回到所有并行轴都还没关掉的那颗旋钮：梯度累积与微批大小，它决定 \\(M\\)、\\(b\\) 以及上述通信体积的常数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲藏通信；只补沿序列切分注意力激活的 Ulysses 布局。</li><li>进出注意力两次 All-to-All，SDPA 公式不变，复杂度仍平方。</li><li>SP 度与 TP 头切分不要重复切碎；序列长度要对齐加载器。</li><li>与 PP 阶段边界的发送是两条通信，优先级要定。</li><li>出处：Jacobs et al., <em>DeepSpeed Ulysses</em>；Korthikanti et al., 序列并行与激活重计算。</li></ul>',4))])}const b=o(h,[["render",m]]);export{T as __pageData,b as default};
